const body = $json.body || {};
const pageId = String(body.pageId || '').replace(/-/g, '');
if (!/^[0-9a-f]{32}$/i.test(pageId)) {
  throw new Error('pageId manquant ou invalide');
}
return [{ json: { pageId } }];

const page = $json;
const pageId = $('Valider Entree').first().json.pageId;

function texte(prop) {
  if (!prop) return '';
  const arr = prop.rich_text || prop.title || [];
  return arr.map(t => t.plain_text || '').join(' ').trim();
}

const p = page.properties || {};
const accroche = texte(p['Accroche']);
const analyse = texte(p['Analyse IA']);
const plateforme = p['Plateforme'] && p['Plateforme'].select ? p['Plateforme'].select.name : '';
const type = p['Type'] && p['Type'].select ? p['Type'].select.name : '';
const angles = p['Angle'] && p['Angle'].multi_select ? p['Angle'].multi_select.map(a => a.name).join(', ') : '';
const score = p['Score surperformance'] ? p['Score surperformance'].number : null;

if (!accroche && !analyse) {
  throw new Error('Publication sans accroche ni analyse : rien pour construire un script');
}

const contexte = [
  'Accroche du post concurrent : ' + accroche,
  analyse ? 'Analyse IA du post : ' + analyse : '',
  plateforme ? 'Plateforme : ' + plateforme + (type ? ' (' + type + ')' : '') : '',
  angles ? 'Angles detectes : ' + angles : '',
  score ? 'Ce post a fait ' + score + ' fois mieux que la moyenne de son compte.' : '',
].filter(Boolean).join('\n');

const prompt = `Tu ecris pour Anna Ollivier, psychologue clinicienne specialisee en developpement emotionnel de l'enfant (methode Ma Boussole Emotionnelle, parents d'enfants 0-12 ans).

Voici une publication concurrente qui a surperforme :

${contexte}

Ta mission : recreer un SCRIPT complet en francais qui reprend l'IDEE DE FOND de ce post, adapte a la voix d'Anna.

Regles strictes :
- Reprends uniquement l'idee psychologique ou educative (le message transmis au parent), JAMAIS le contexte de mise en scene du post original (lieu, personnages, anecdote).
- Structure le script : ACCROCHE (3 secondes, une phrase qui arrete le scroll), CORPS (l'idee developpee simplement, ton d'amie experte, une pointe de neurosciences vulgarisees), CONCLUSION (une phrase d'espoir actionnable).
- Francais naturel et oral, phrases courtes, zero jargon non explique.
- Pas de hashtags, pas d'emojis, maximum 220 mots.
- Termine par une ligne "Idee source :" resumant en une phrase l'idee du post concurrent.

Reponds UNIQUEMENT avec le script, sans preambule ni commentaire.`;

return [{ json: { pageId, prompt } }];

const pageId = $('Valider Entree').first().json.pageId;
const rep = $json;
const contenu = (((rep.message || {}).content) || '').trim();
if (!contenu) {
  throw new Error('Reponse LLM vide : ' + JSON.stringify(rep).slice(0, 300));
}
return [{ json: { pageId, scriptGenere: contenu.slice(0, 1900) } }];
